create extension if not exists pgcrypto;
create table if not exists employees(id uuid primary key default gen_random_uuid(),name text unique not null,role text default '',pin text default '',employment_type text default 'full' check (employment_type in ('full','part')),default_shift_id text,custom_time text,active boolean default true,sort int default 0);
create table if not exists timeoff_requests(week_start date not null,employee_id uuid references employees(id) on delete cascade,day int not null check(day between 0 and 6),note text default '',updated_at timestamptz default now(),primary key(week_start,employee_id));
create table if not exists weekly_schedules(week_start date primary key,assignments jsonb not null,warnings jsonb default '[]',generated_at timestamptz default now(),published_at timestamptz,publish_requested_at timestamptz);
create table if not exists app_settings(id int primary key default 1,value jsonb not null); alter table employees enable row level security; alter table timeoff_requests enable row level security; alter table weekly_schedules enable row level security; alter table app_settings enable row level security; create policy "anon access" on employees for all using(true) with check(true); create policy "anon access" on timeoff_requests for all using(true) with check(true); create policy "anon access" on weekly_schedules for all using(true) with check(true); create policy "anon access" on app_settings for all using(true) with check(true);
